"use client";

import { Calendar as AriaCalendar, RangeCalendar as AriaRangeCalendar } from "react-aria-components";
import type {
  CalendarProps as AriaCalendarProps,
  DateValue,
  RangeCalendarProps as AriaRangeCalendarProps,
} from "react-aria-components";
import { MonthPanel } from "@/components/ui/date-picker/shared";
import { cx } from "@/lib/utils";

/**
 * Date calendar — a month on the page rather than in a popover: pick a day
 * for a booking, a deadline, a range of nights.
 *
 *   <DateCalendar aria-label="Delivery date" value={date} onChange={setDate} />
 *   <DateRangeCalendar aria-label="Stay" value={range} onChange={setRange} />
 *
 * Date Picker's month panel, as is: the card, the 16px month chevrons, the
 * 32px day cells 12px apart with the selected day's accent pill and the
 * range band that bridges the gaps. Today carries a small accent dot, and
 * days ruled out by `isDateUnavailable` are struck through.
 *
 * Built on React Aria's Calendar and RangeCalendar: arrows move by day,
 * Page Up and Page Down by month (with Shift, by year), Home and End to the
 * month's first and last day, and Enter picks. `minValue` and `maxValue`
 * fade the days outside them. Values are dates from @internationalized/date.
 */

export interface DateCalendarProps<T extends DateValue> extends Omit<AriaCalendarProps<T>, "className" | "children" | "visibleDuration"> {
  /** Mark today with a dot. Default true. */
  showToday?: boolean;
  className?: string;
}

export function DateCalendar<T extends DateValue>({ showToday = true, className, ...props }: DateCalendarProps<T>) {
  return (
    <AriaCalendar {...props} className={cx("inline-flex outline-none", className)}>
      <MonthPanel offset={0} showPrev showNext showToday={showToday} />
    </AriaCalendar>
  );
}

export interface DateRangeCalendarProps<T extends DateValue>
  extends Omit<AriaRangeCalendarProps<T>, "className" | "children" | "visibleDuration"> {
  /** One month, or two side by side (default). They stack when the space is narrow. */
  visibleMonths?: 1 | 2;
  /** Mark today with a dot. Default true. */
  showToday?: boolean;
  className?: string;
}

export function DateRangeCalendar<T extends DateValue>({
  visibleMonths = 2,
  showToday = true,
  className,
  ...props
}: DateRangeCalendarProps<T>) {
  return (
    <AriaRangeCalendar
      {...props}
      visibleDuration={{ months: visibleMonths }}
      className={cx("inline-flex outline-none", className)}
    >
      <div className="flex flex-wrap justify-center gap-2">
        {visibleMonths === 2 ? (
          <>
            <MonthPanel offset={0} showPrev showToday={showToday} />
            <MonthPanel offset={1} showNext showToday={showToday} />
          </>
        ) : (
          <MonthPanel offset={0} showPrev showNext showToday={showToday} />
        )}
      </div>
    </AriaRangeCalendar>
  );
}

"use client";

import { useTemplateCopy } from "@/components/ui/template-copy/template-copy";

import { useEffect, useRef, useState } from "react";
import type { RefObject } from "react";
import { Calendar, Dialog, Popover, useLocale } from "react-aria-components";
import type { CalendarDate } from "@internationalized/date";
import { RiCalendarLine } from "@remixicon/react";
import { AnimatePresence, motion } from "motion/react";
import { Button } from "@/components/ui/buttons/button";
import {
  DateChipInput,
  MonthPanel,
  formatTriggerDate,
  popoverClassName,
  triggerButtonClassName,
} from "@/components/ui/date-picker/shared";
import { cx } from "@/lib/utils";
import { useDismissOnOutsidePress } from "@/lib/use-dismiss-on-outside-press";

/**
 * Figma source: Board UI → "Calendar_single" (node 3879:6708).
 *
 * A single-date picker: trigger button opens a popover with one month
 * (react-aria's plain `Calendar`, so both nav chevrons are fully functional —
 * unlike `DateRangePicker`'s dual view, there's only one month to navigate)
 * and a footer with an editable "DD/MM/YYYY" chip plus Cancel/Apply. No
 * quick-select sidebar in this Figma frame.
 *
 * Reuses the exact chevrons, day-cell rendering, month-panel chrome, editable
 * date chip, and trigger/popover surfaces built for `DateRangePicker` — see
 * `./shared`. A plain `Calendar`'s `CalendarCellRenderProps` always reports
 * `isSelectionStart === isSelectionEnd === isSelected` for the one chosen
 * day, so the shared `DayCell` renders it as a single fully-rounded pill
 * with no connecting range background, matching Figma without any
 * single-vs-range branching in the cell itself.
 *
 * Standalone `Popover` + `triggerRef` (like `MeetingScheduler`), not
 * `DialogTrigger`, so an external trigger can be swapped in: pass
 * `triggerRef`/`isOpen`/`onOpenChange` to anchor the popover to your own
 * element (e.g. the calendar template's month-switcher label) instead of
 * DatePicker's own button, which is hidden in that case.
 */

export interface DatePickerProps {
  value?: CalendarDate | null;
  defaultValue?: CalendarDate | null;
  onChange?: (value: CalendarDate | null) => void;
  isDisabled?: boolean;
  className?: string;
  "aria-label"?: string;
  /** Anchor the popover to an external element instead of DatePicker's own
   *  trigger button (which is hidden when this is provided). Pair with
   *  `isOpen`/`onOpenChange` for full external control. */
  triggerRef?: RefObject<HTMLElement | null>;
  isOpen?: boolean;
  onOpenChange?: (isOpen: boolean) => void;
}

export function DatePicker({
  value,
  defaultValue = null,
  onChange,
  isDisabled,
  className,
  "aria-label": ariaLabel = "Date",
  triggerRef: externalTriggerRef,
  isOpen: controlledIsOpen,
  onOpenChange: controlledOnOpenChange,
}: DatePickerProps) {
  const localize = useTemplateCopy();
  const { locale } = useLocale();
  const ownTriggerRef = useRef<HTMLButtonElement>(null);
  const triggerRef = externalTriggerRef ?? ownTriggerRef;
  const isExternal = externalTriggerRef !== undefined;
  const popoverRef = useRef<HTMLElement>(null);

  const [internalOpen, setInternalOpen] = useState(false);
  const isOpen = isExternal ? (controlledIsOpen ?? false) : internalOpen;
  const setIsOpen = isExternal ? (controlledOnOpenChange ?? (() => {})) : setInternalOpen;

  const isControlled = value !== undefined;
  const [internalValue, setInternalValue] = useState<CalendarDate | null>(defaultValue);
  const committedValue = isControlled ? (value ?? null) : internalValue;

  const [pendingValue, setPendingValue] = useState<CalendarDate | null>(committedValue);
  // React Aria's `Calendar` keeps its own internal `visibleRange` state for
  // as long as it stays mounted (Popover keeps its content mounted between
  // opens for the exit animation), so it never re-derives the visible month
  // from a later `value` change on its own. Bumping this on every open and
  // keying `Calendar` on it forces a fresh mount showing the right month —
  // needed for the external-trigger case, where `value` can jump (e.g. the
  // calendar template's month switcher) between one open and the next.
  const [openKey, setOpenKey] = useState(0);

  // Re-sync the calendar's displayed month/selection to the current
  // committed value every time the popover opens — not just when DatePicker's
  // own trigger toggles it, but also when `isOpen` is flipped true by an
  // external trigger (`triggerRef`), which never runs `openChange` below.
  useEffect(() => {
    if (isOpen) {
      setPendingValue(committedValue);
      setOpenKey((k) => k + 1);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- resync on the open transition only, not every committedValue change
  }, [isOpen]);

  const commit = (next: CalendarDate | null) => {
    if (!isControlled) setInternalValue(next);
    onChange?.(next);
    setIsOpen(false);
  };

  const openChange = (open: boolean) => {
    setIsOpen(open);
  };

  useDismissOnOutsidePress(isOpen, () => setIsOpen(false), [triggerRef, popoverRef]);

  return localize((
    <>
      {!isExternal && (
        <button
          ref={ownTriggerRef}
          type="button"
          disabled={isDisabled}
          onClick={() => openChange(!isOpen)}
          className={cx(triggerButtonClassName, className)}
        >
          <RiCalendarLine className="size-5 shrink-0 text-foreground-icon-primary" aria-hidden />
          <span className="flex items-center justify-center whitespace-nowrap px-1 text-body-medium text-text-primary">
            {committedValue ? formatTriggerDate(committedValue, locale) : "Select date"}
          </span>
        </button>
      )}
      <Popover
        ref={popoverRef}
        triggerRef={triggerRef}
        isOpen={isOpen}
        onOpenChange={openChange}
        offset={4}
        placement="bottom end"
        isNonModal
        className={popoverClassName}
      >
        <Dialog aria-label={ariaLabel} className="outline-none">
          <Calendar key={openKey} aria-label={ariaLabel} value={pendingValue} onChange={setPendingValue}>
            <div className="flex flex-col pt-2 pe-2 pb-3 ps-2">
              <MonthPanel offset={0} showPrev showNext />
              <div className="flex items-center justify-between pt-3 pe-4 ps-4">
                <div>
                  <AnimatePresence>
                    {pendingValue && (
                      <motion.div
                        key="date-summary"
                        initial={{ opacity: 0, y: -12 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -12 }}
                        transition={{ duration: 0.25, ease: [0.34, 1.2, 0.64, 1] }}
                      >
                        <DateChipInput date={pendingValue} label="Date" onCommit={setPendingValue} />
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>
                <div className="flex items-center gap-2.5">
                  <Button
                    variant="secondary"
                    onClick={() => {
                      setPendingValue(committedValue);
                      setIsOpen(false);
                    }}
                  >
                    Cancel
                  </Button>
                  <Button onClick={() => commit(pendingValue)} disabled={!pendingValue}>
                    Apply
                  </Button>
                </div>
              </div>
            </div>
          </Calendar>
        </Dialog>
      </Popover>
    </>
  ));
}

"use client";

import { useMemo, useRef, useState } from "react";
import {
  Button as AriaButton,
  Dialog,
  DialogTrigger,
  Popover,
  RangeCalendar,
  useLocale,
} from "react-aria-components";
import {
  CalendarDate,
  endOfMonth,
  endOfYear,
  getLocalTimeZone,
  isSameDay,
  startOfMonth,
  startOfYear,
  today,
} from "@internationalized/date";
import { RiCalendarLine } from "@remixicon/react";
import { AnimatePresence, motion } from "motion/react";
import { Button } from "@/components/ui/buttons/button";
import { useTemplateCopy } from "@/components/ui/template-copy/template-copy";
import {
  DateChipInput,
  MonthPanel,
  formatTriggerDate,
  popoverClassName,
  triggerButtonClassName,
} from "@/components/ui/date-picker/shared";
import { cx } from "@/lib/utils";
import { useDismissOnOutsidePress, useTriggerToggle } from "@/lib/use-dismiss-on-outside-press";

/**
 * Figma source: Board UI → "Calendar" (node 3871:5738).
 *
 * A dual-month date range picker: trigger button opens a popover with a
 * quick-select sidebar, two adjacent months (react-aria's
 * `visibleDuration={{ months: 2 }}`), and a footer with read-only date chips,
 * a "N days selected" pill, and Cancel/Apply.
 *
 * Two deliberate departures from the raw Figma frame:
 *  - The prev/next chevrons in Figma appear on *both* sides of *both* month
 *    headers (4 total), pre-rotated generic vector exports. A dual-month
 *    calendar only has one navigation state (the two months always stay
 *    adjacent), so only the outer two chevrons (prev on month 1, next on
 *    month 2) are wired up; the inner two slots are kept as invisible
 *    spacers rather than dead click targets, preserving Figma's header
 *    spacing without fake buttons.
 *  - The connecting range background (Figma: one hardcoded `bg-blue-100`
 *    rectangle sized for the one example range shown) is generalized into a
 *    per-cell layered background driven by react-aria's `isSelectionStart` /
 *    `isSelectionEnd` state, so any range length/position renders correctly.
 *
 * Colors/radii/spacing (semantic range-selection blues, blue-500/600,
 * radius/2lg/xl/2xl/3xl,
 * shadow-xs, background/secondary/default, background/tertiary/default,
 * border/button/default) are Tailwind v4 defaults or existing semantic
 * tokens — see styles/theme.css.
 *
 * Shared chrome (chevrons, day cell, month panel, editable date chip, trigger
 * + popover surfaces) lives in `./shared` — `DatePicker` (single-month,
 * non-range) reuses the same pieces.
 */

export interface DateRangeValue {
  start: CalendarDate;
  end: CalendarDate;
}

export interface DateRangePickerProps {
  value?: DateRangeValue | null;
  defaultValue?: DateRangeValue | null;
  onChange?: (value: DateRangeValue | null) => void;
  isDisabled?: boolean;
  className?: string;
  /** Extra classes for the portalled calendar, such as a locale-specific font. */
  popoverClassName?: string;
  "aria-label"?: string;
  /** Trigger text shown when no range is committed yet. Default "Select date range". */
  placeholder?: string;
}

function daysInRange(value: DateRangeValue) {
  const tz = getLocalTimeZone();
  const ms = value.end.toDate(tz).getTime() - value.start.toDate(tz).getTime();
  return Math.round(ms / 86_400_000) + 1;
}

function useQuickSelectPresets() {
  return useMemo(() => {
    const now = today(getLocalTimeZone());
    const lastMonth = now.subtract({ months: 1 });
    const lastYear = now.subtract({ years: 1 });
    return [
      { label: "Today", range: { start: now, end: now } },
      { label: "Yesterday", range: { start: now.subtract({ days: 1 }), end: now.subtract({ days: 1 }) } },
      { label: "Last week", range: { start: now.subtract({ days: 7 }), end: now.subtract({ days: 1 }) } },
      { label: "This month", range: { start: startOfMonth(now), end: endOfMonth(now) } },
      { label: "Last month", range: { start: startOfMonth(lastMonth), end: endOfMonth(lastMonth) } },
      { label: "This year", range: { start: startOfYear(now), end: endOfYear(now) } },
      { label: "Last year", range: { start: startOfYear(lastYear), end: endOfYear(lastYear) } },
      { label: "All time", range: { start: now.subtract({ years: 10 }), end: now } },
    ];
  }, []);
}

function isPresetActive(value: DateRangeValue | null, range: DateRangeValue) {
  return !!value && isSameDay(value.start, range.start) && isSameDay(value.end, range.end);
}

function QuickSelect({
  value,
  onSelect,
}: {
  value: DateRangeValue | null;
  onSelect: (range: DateRangeValue) => void;
}) {
  const localize = useTemplateCopy();
  const presets = useQuickSelectPresets();

  return localize((
    <div className="flex w-[118px] shrink-0 flex-col gap-1.5">
      {presets.map((preset) => (
        <button
          key={preset.label}
          type="button"
          onClick={() => onSelect(preset.range)}
          className={cx(
            "w-full cursor-pointer rounded-2lg px-2 py-1.5 text-start text-body-medium text-text-primary transition-colors duration-150 ease",
            isPresetActive(value, preset.range)
              ? "bg-background-tertiary-default"
              : "hover:bg-background-secondary-hover",
          )}
        >
          {preset.label}
        </button>
      ))}
    </div>
  ));
}

function Footer({
  value,
  onChange,
  onCancel,
  onApply,
}: {
  value: DateRangeValue | null;
  onChange: (value: DateRangeValue) => void;
  onCancel: () => void;
  onApply: () => void;
}) {
  const localize = useTemplateCopy();
  return localize((
    <div className="flex items-center justify-between pt-3 pe-4">
      <div className="flex items-center gap-2.5">
        <AnimatePresence>
          {value && (
            <motion.div
              key="range-summary"
              initial={{ opacity: 0, y: -12 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -12 }}
              transition={{ duration: 0.25, ease: [0.34, 1.2, 0.64, 1] }}
              className="flex items-center gap-2.5"
            >
              <div className="flex items-center gap-[5px]">
                <DateChipInput
                  date={value.start}
                  label="Start date"
                  onCommit={(start) =>
                    onChange({ start, end: start.compare(value.end) > 0 ? start : value.end })
                  }
                />
                <span className="text-body-medium text-text-secondary">-</span>
                <DateChipInput
                  date={value.end}
                  label="End date"
                  onCommit={(end) =>
                    onChange({ start: end.compare(value.start) < 0 ? end : value.start, end })
                  }
                />
              </div>
              <span className="rounded-xl bg-background-tertiary-default px-2 py-2 text-body-medium text-text-secondary">
                {`${daysInRange(value)} day${daysInRange(value) === 1 ? "" : "s"} selected`}
              </span>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
      <div className="flex items-center gap-2.5">
        <Button variant="secondary" onClick={onCancel}>
          Cancel
        </Button>
        <Button onClick={onApply} disabled={!value}>
          Apply
        </Button>
      </div>
    </div>
  ));
}

export function DateRangePicker({
  value,
  defaultValue = null,
  onChange,
  isDisabled,
  className,
  popoverClassName: calendarClassName,
  "aria-label": ariaLabel = "Date range",
  placeholder = "Select date range",
}: DateRangePickerProps) {
  const localize = useTemplateCopy();
  const { locale } = useLocale();
  const isControlled = value !== undefined;
  const [internalValue, setInternalValue] = useState<DateRangeValue | null>(defaultValue);
  const committedValue = isControlled ? (value ?? null) : internalValue;

  const [pendingValue, setPendingValue] = useState<DateRangeValue | null>(committedValue);

  const commit = (next: DateRangeValue | null) => {
    if (!isControlled) setInternalValue(next);
    onChange?.(next);
  };

  const [isOpen, setIsOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const popoverRef = useRef<HTMLElement>(null);
  useDismissOnOutsidePress(isOpen, () => setIsOpen(false), [triggerRef, popoverRef]);
  // Pressing the trigger while open closes the popover instead of reopening
  const allowOpenChange = useTriggerToggle(isOpen, triggerRef);

  return localize((
    <DialogTrigger
      isOpen={isOpen}
      onOpenChange={(open) => {
        if (!allowOpenChange(open)) return;
        if (open) setPendingValue(committedValue);
        setIsOpen(open);
      }}
    >
      <AriaButton ref={triggerRef} isDisabled={isDisabled} className={cx(triggerButtonClassName, className)}>
        <RiCalendarLine className="size-5 shrink-0 text-foreground-icon-primary" aria-hidden />
        <span className="flex items-center justify-center whitespace-nowrap px-1 text-body-medium text-text-primary">
          {committedValue ? `${formatTriggerDate(committedValue.start, locale)} - ${formatTriggerDate(committedValue.end, locale)}` : placeholder}
        </span>
      </AriaButton>
      <Popover ref={popoverRef} offset={4} placement="bottom end" isNonModal className={cx(popoverClassName, calendarClassName)}>
        <Dialog aria-label={ariaLabel} className="outline-none">
          {({ close }) => (
            <RangeCalendar
              aria-label={ariaLabel}
              visibleDuration={{ months: 2 }}
              value={pendingValue}
              onChange={setPendingValue}
            >
              <div className="flex gap-3">
                <div className="pt-4 ps-4">
                  <QuickSelect
                    value={pendingValue}
                    onSelect={(range) => setPendingValue(range)}
                  />
                </div>
                <div className="flex flex-col pt-2 pe-2 pb-3">
                  <div className="flex gap-2">
                    <MonthPanel offset={0} showPrev />
                    <MonthPanel offset={1} showNext />
                  </div>
                  <Footer
                    value={pendingValue}
                    onChange={setPendingValue}
                    onCancel={() => {
                      setPendingValue(committedValue);
                      close();
                    }}
                    onApply={() => {
                      commit(pendingValue);
                      close();
                    }}
                  />
                </div>
              </div>
            </RangeCalendar>
          )}
        </Dialog>
      </Popover>
    </DialogTrigger>
  ));
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import type { ReactNode } from "react";
import { Calendar, Dialog, Popover } from "react-aria-components";
import { CalendarDate, getLocalTimeZone, today } from "@internationalized/date";
import { RiCalendarLine, RiFlagLine, RiGlobalLine } from "@remixicon/react";
import { Avatar } from "@/components/ui/avatar/avatar";
import { Button } from "@/components/ui/buttons/button";
import { ChevronDownSmall } from "@/components/ui/icons/chevrons";
import { MonthPanel, popoverClassName, triggerButtonClassName } from "@/components/ui/date-picker/shared";
import { cx } from "@/lib/utils";
import { useDismissOnOutsidePress } from "@/lib/use-dismiss-on-outside-press";

/**
 * Figma source: Board UI → "Meeting" (node 3881:7618).
 *
 * A Calendly/Cal.com-style booking panel: host card + meeting summary on the
 * left, a single-month calendar in the middle (reusing `MonthPanel` from
 * `./shared`), and a timezone / hour-format / time-slot sidebar on the
 * right. Like the other two pickers, the panel is a real react-aria
 * `Popover` — but since there's no `DialogTrigger` here (the trigger is a
 * plain button, not a `Dialog`), it's wired up via `triggerRef` + controlled
 * `isOpen` instead. That keeps the panel a portaled overlay that never
 * affects layout, so the trigger (Figma's own top-right chip, repurposed
 * from a static readout into the open/close control) can sit compactly
 * next to other trigger buttons instead of dragging a whole row wide.
 *
 * Two deliberate departures from the raw Figma frame:
 *  - The time-slot list (Figma: a static "14:00"..."18:30" mock that then
 *    repeats "14:00" a 14th time — clearly a copy/paste artifact, not real
 *    data) is generated as a real fixed 09:00–18:30 half-hour range instead.
 *  - The timezone row and the duration/language/conferencing rows are
 *    Figma "Dropdown" layers, but only the timezone row actually has a
 *    chevron — the other three are read-only summary rows here, matching
 *    what's visually present rather than the layer name.
 */

export interface MeetingSchedulerHost {
  name: string;
  email: string;
  avatarInitial: string;
}

export interface MeetingSchedulerDetails {
  title: string;
  description?: string;
  durationMinutes: number;
  language?: string;
  conferencing?: string;
}

export interface MeetingSchedulerValue {
  date: CalendarDate;
  /** 24h "HH:mm", or `null` when a date is picked but no time slot yet. */
  time: string | null;
}

export interface MeetingSchedulerProps {
  host?: MeetingSchedulerHost;
  meeting?: MeetingSchedulerDetails;
  timezone?: string;
  value?: MeetingSchedulerValue | null;
  defaultValue?: MeetingSchedulerValue | null;
  onChange?: (value: MeetingSchedulerValue | null) => void;
  /** Render the panel open on mount. Default `false`. */
  defaultOpen?: boolean;
  className?: string;
  "aria-label"?: string;
  /** Trigger button text. Default "Schedule a meeting". */
  triggerLabel?: string;
}

const DEFAULT_HOST: MeetingSchedulerHost = {
  name: "Mertcan Esmergul",
  email: "hi@mertcan.works",
  avatarInitial: "M",
};

const DEFAULT_MEETING: MeetingSchedulerDetails = {
  title: "30 min intro meeting",
  description: "Let's discuss your design needs and how we can collaborate 🥳",
  durationMinutes: 30,
  language: "English",
  conferencing: "Google meet",
};

function useTimeSlots() {
  return useMemo(() => {
    const slots: string[] = [];
    for (let minutes = 9 * 60; minutes <= 18 * 60 + 30; minutes += 30) {
      const h = Math.floor(minutes / 60);
      const m = minutes % 60;
      slots.push(`${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`);
    }
    return slots;
  }, []);
}

function formatTime(time: string, use24h: boolean) {
  const [h, m] = time.split(":").map(Number);
  if (use24h) return time;
  const period = h >= 12 ? "PM" : "AM";
  const hour12 = h % 12 === 0 ? 12 : h % 12;
  return `${hour12}:${String(m).padStart(2, "0")} ${period}`;
}

function formatChipDateTime(value: MeetingSchedulerValue) {
  const date = new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric", year: "numeric" }).format(
    value.date.toDate(getLocalTimeZone()),
  );
  return { date, time: value.time ?? "Select a time" };
}

function InfoRow({ icon, children }: { icon: ReactNode; children: ReactNode }) {
  return (
    <div className="flex items-center gap-[5px] text-body-medium text-text-primary">
      {icon}
      {children}
    </div>
  );
}

function GlyphIcon({ icon: Icon }: { icon: typeof RiGlobalLine }) {
  return <Icon className="size-5 shrink-0 text-foreground-icon-primary" aria-hidden />;
}

/** Figma's exact Google Meet mark, 20×20 (`public/brand/google_meet.png`). */
function GoogleMeetIcon() {
  return <img src="/brand/google_meet.png" alt="" width={20} height={20} className="size-5 shrink-0" />;
}

function HourFormatToggle({ use24h, onChange }: { use24h: boolean; onChange: (use24h: boolean) => void }) {
  return (
    <div className="flex shrink-0 items-start gap-0.5 rounded-2lg">
      {(["12h", "24h"] as const).map((label, i) => {
