export function MeetingScheduler({
  host = DEFAULT_HOST,
  meeting = DEFAULT_MEETING,
  timezone = "Amsterdam",
  value,
  defaultValue = null,
  onChange,
  defaultOpen = false,
  className,
  "aria-label": ariaLabel = "Schedule meeting",
  triggerLabel = "Schedule a meeting",
}: MeetingSchedulerProps) {
  const triggerRef = useRef<HTMLButtonElement>(null);
  const popoverRef = useRef<HTMLElement>(null);
  const timeSlots = useTimeSlots();
  const isControlled = value !== undefined;
  const [internalValue, setInternalValue] = useState<MeetingSchedulerValue | null>(
    defaultValue ?? { date: today(getLocalTimeZone()), time: null },
  );
  const committedValue = isControlled ? value : internalValue;

  const [pendingValue, setPendingValue] = useState<MeetingSchedulerValue | null>(committedValue);
  const [use24h, setUse24h] = useState(true);
  // Never honor `defaultOpen` on the initial render: the ~700px-wide panel
  // being in the very first paint makes mobile Safari compute its layout
  // viewport from that width, permanently zooming the whole page out even
  // after the panel closes. Open it post-mount instead, and only on
  // viewports wide enough to show the panel without overflowing.
  const [isOpen, setIsOpen] = useState(false);
  useEffect(() => {
    if (!defaultOpen) return;
    if (window.matchMedia("(min-width: 640px)").matches) {
      setIsOpen(true);
    }
  }, [defaultOpen]);

  const commit = (next: MeetingSchedulerValue | null) => {
    if (!isControlled) setInternalValue(next);
    onChange?.(next);
    setIsOpen(false);
  };

  useDismissOnOutsidePress(isOpen, () => setIsOpen(false), [triggerRef, popoverRef]);

  const chip = pendingValue ? formatChipDateTime(pendingValue) : null;
  const dayChip = pendingValue
    ? {
        weekday: new Intl.DateTimeFormat(undefined, { weekday: "short" }).format(pendingValue.date.toDate(getLocalTimeZone())).slice(0, 2),
        day: pendingValue.date.day,
      }
    : null;

  return (
    <>
      <button
        ref={triggerRef}
        type="button"
        onClick={() => {
          if (!isOpen) setPendingValue(committedValue);
          setIsOpen((open) => !open);
        }}
        className={cx(triggerButtonClassName, className)}
      >
        <RiCalendarLine className="size-5 shrink-0 text-foreground-icon-primary" aria-hidden />
        <span className="flex items-center justify-center whitespace-nowrap px-1 text-body-medium text-text-primary">
          {triggerLabel}
        </span>
        <ChevronDownSmall
          className={cx("size-4 shrink-0 text-text-secondary transition-transform duration-200 ease", isOpen && "rotate-180")}
        />
      </button>
      <Popover
        ref={popoverRef}
        triggerRef={triggerRef}
        isOpen={isOpen}
        onOpenChange={setIsOpen}
        placement="bottom end"
        offset={8}
        isNonModal
        className={popoverClassName}
      >
        <Dialog aria-label={ariaLabel} className="outline-none">
          <Calendar
            aria-label={ariaLabel}
            value={pendingValue?.date ?? null}
            onChange={(date) => setPendingValue((prev) => ({ date, time: prev?.time ?? null }))}
          >
            <div className="flex h-[429px] gap-4">
              {/* Host + meeting summary */}
              <div className="flex w-[207px] shrink-0 flex-col gap-4 py-4 ps-4">
                <div className="flex flex-col items-start gap-2">
                  <Avatar size="md" color="blue" initials={host.avatarInitial} />
                  <div className="flex flex-col text-body-medium">
                    <span className="text-text-primary">{host.name}</span>
                    <span className="text-text-secondary">{host.email}</span>
                  </div>
                </div>
                <div className="flex flex-col gap-1">
                  <p className="text-title-3-medium text-text-primary">{meeting.title}</p>
                  {meeting.description && (
                    <p className="text-body-2-medium text-text-secondary">{meeting.description}</p>
                  )}
                </div>
                <div className="mt-auto flex flex-col gap-3">
                  <InfoRow icon={<GlyphIcon icon={RiGlobalLine} />}>{meeting.durationMinutes} minutes</InfoRow>
                  {meeting.language && <InfoRow icon={<GlyphIcon icon={RiFlagLine} />}>{meeting.language}</InfoRow>}
                  {meeting.conferencing && <InfoRow icon={<GoogleMeetIcon />}>{meeting.conferencing}</InfoRow>}
                </div>
              </div>

              {/* Calendar + footer */}
              <div className="flex flex-col gap-3 pt-2 pb-3">
                <MonthPanel offset={0} showPrev showNext />
                <div className="flex items-center justify-between">
                  <span className="flex items-center gap-1.5 rounded-2lg border border-border-button-default bg-background-primary-default px-2 py-2 text-body-medium text-text-primary shadow-xs">
                    {chip && (
                      <>
                        <span>{chip.date}</span>
                        <span className="text-text-secondary">{chip.time}</span>
                      </>
                    )}
                  </span>
                  <Button onClick={() => commit(pendingValue)} disabled={!pendingValue?.time}>
                    Send meeting
                  </Button>
                </div>
              </div>

              {/* Timezone + hour format + time slots */}
              <div className="flex h-full w-[170px] shrink-0 flex-col gap-3 overflow-hidden pt-4 pe-4">
                <button
                  type="button"
                  className="flex cursor-pointer items-center justify-between rounded-2lg outline-none"
                >
                  <span className="flex items-center gap-[5px] text-body-medium text-text-primary">
                    <RiGlobalLine className="size-5 shrink-0 text-foreground-icon-primary" aria-hidden />
                    {timezone}
                  </span>
                  <ChevronDownSmall className="size-4 shrink-0 text-text-secondary" />
                </button>

                <div className="flex items-center justify-between">
                  {dayChip && (
                    <span className="inline-flex items-center gap-[3px] rounded-2lg bg-background-tertiary-default px-2 py-1 text-body-medium">
                      <span className="text-text-primary">{dayChip.weekday}</span>
                      <span className="text-text-secondary">{dayChip.day}</span>
                    </span>
                  )}
                  <HourFormatToggle use24h={use24h} onChange={setUse24h} />
                </div>

                <div
                  className="flex min-h-0 flex-1 flex-col gap-2 overflow-y-auto pb-3"
                  style={{
                    maskImage: "linear-gradient(to bottom, transparent, black 16px, black 100%)",
                    WebkitMaskImage: "linear-gradient(to bottom, transparent, black 16px, black 100%)",
                  }}
                >
                  {timeSlots.map((slot) => (
                    <button
                      key={slot}
                      type="button"
                      onClick={() =>
                        setPendingValue((prev) => ({ date: prev?.date ?? today(getLocalTimeZone()), time: slot }))
                      }
                      className={cx(
                        "w-full shrink-0 cursor-pointer rounded-2lg px-2 py-1.5 text-center text-body-medium text-text-primary transition-colors duration-150 ease",
                        pendingValue?.time === slot
                          ? "bg-background-tertiary-default"
                          : "hover:bg-background-secondary-hover",
                      )}
                    >
                      {formatTime(slot, use24h)}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </Calendar>
        </Dialog>
      </Popover>
    </>
  );
}

"use client";

import { useEffect, useState, useContext } from "react";
import {
  Button as RACButton,
  CalendarCell,
  CalendarGrid,
  CalendarGridBody,
  CalendarGridHeader,
  CalendarHeaderCell,
  CalendarStateContext,
  RangeCalendarStateContext,
  useLocale,
} from "react-aria-components";
import type { CalendarCellRenderProps } from "react-aria-components";
import { CalendarDate, endOfWeek, getLocalTimeZone, isSameDay, startOfWeek } from "@internationalized/date";
import { cx } from "@/lib/utils";

/**
 * Shared building blocks for the base/date-picker family — `DateRangePicker`
 * (dual-month, node 3871:5738) and `DatePicker` (single-month, node
 * 3879:6708) are the same visual system (month panel, day cell, editable
 * date chip) around two different react-aria-components roots
 * (`RangeCalendar` vs `Calendar`). Keeping the pieces here means a Figma
 * fidelity fix only has to happen once.
 */

/** Exact paths from Figma's month-nav chevrons (node 3869:5461 / 3869:5528) — a
 *  16×16 glyph, 2px round-capped stroke, mirrored around x=8. */
export function ChevronLeft16({ className }: { className?: string }) {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" className={cx("rtl:rotate-180", className)} aria-hidden>
      <path
        d="M9 4L5.70711 7.29289C5.31658 7.68342 5.31658 8.31658 5.70711 8.70711L9 12"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
      />
    </svg>
  );
}

export function ChevronRight16({ className }: { className?: string }) {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" className={cx("rtl:rotate-180", className)} aria-hidden>
      <path
        d="M7 4L10.2929 7.29289C10.6834 7.68342 10.6834 8.31658 10.2929 8.70711L7 12"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
      />
    </svg>
  );
}

export function formatTriggerDate(date: CalendarDate, locale?: string) {
  return new Intl.DateTimeFormat(locale, { month: "short", day: "numeric", year: "numeric" }).format(
    date.toDate(getLocalTimeZone()),
  );
}

export function formatChipDate(date: CalendarDate) {
  return `${String(date.day).padStart(2, "0")}/${String(date.month).padStart(2, "0")}/${date.year}`;
}

/** Parses the chip's own "DD/MM/YYYY" format back into a CalendarDate, or
 *  null if the text isn't a valid date (out-of-range day/month is rejected
 *  up front; CalendarDate itself constrains impossible day-in-month combos
 *  like Feb 30). */
export function parseChipDate(text: string): CalendarDate | null {
  const match = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(text.trim());
  if (!match) return null;
  const day = Number(match[1]);
  const month = Number(match[2]);
  const year = Number(match[3]);
  if (month < 1 || month > 12 || day < 1 || day > 31) return null;
  return new CalendarDate(year, month, day);
}

export function DayCell(props: CalendarCellRenderProps & { isRange: boolean; showToday?: boolean }) {
  const { locale } = useLocale();
  const { date, formattedDate, isSelected, isSelectionStart, isSelectionEnd, isHovered, isFocusVisible, isDisabled, isUnavailable, isToday, isOutsideMonth, isRange, showToday = false } = props;

  if (isOutsideMonth) {
    return <div className="size-8" />;
  }

  const isWeekStart = isSameDay(date, startOfWeek(date, locale));
  const isWeekEnd = isSameDay(date, endOfWeek(date, locale));

  // A plain (non-range) Calendar never sets isSelectionStart/isSelectionEnd —
  // those are range-only concepts, so they stay false even for the one
  // selected day. Without isRange, that day would fall through to the
  // "middle of a range" backdrop path instead of rendering as its own pill.
  const isSingleDay = isRange ? isSelectionStart && isSelectionEnd : isSelected;
  const isEdge = isRange ? isSelectionStart || isSelectionEnd : isSelected;

  // Cells sit 12px apart (Figma's row/column gap). A selected range should
  // still read as one continuous band, so the background bridges that gap by
  // extending half of it (6px) toward each selected neighbor — never past
  // the first/last column of a row, where there's no neighbor to bridge to.
  // Only meaningful for a RangeCalendar; a plain Calendar never bridges.
  const extendStart = isRange && isSelected && !isSelectionStart && !isWeekStart;
  const extendEnd = isRange && isSelected && !isSelectionEnd && !isWeekEnd;

  // The blue backgrounds fade in/out on opacity instead of popping instantly.
  // Both layers always render (geometry computed regardless of selection) so
  // toggling opacity is a plain CSS transition, not a mount/unmount — that
  // keeps ~70 cells worth of range changes cheap and reliably animated.
  // border-radius rides the same transition as opacity: the rounding classes
  // still flip instantly on deselect (the shape a cell "should" have has no
  // in-between state), but transitioning the property means it eases toward
  // square in sync with the fade instead of snapping to square immediately
  // while the color is still visible.
  return (
    <div className="relative size-8">
      <span
        aria-hidden
        className={cx(
          "absolute inset-y-0 bg-date-range-background transition-[opacity,border-radius] duration-100 ease-out",
          isSelectionStart ? "start-1/2" : extendStart ? "-start-1.5" : "start-0",
          isSelectionEnd ? "end-1/2" : extendEnd ? "-end-1.5" : "end-0",
          !isSelectionStart && isWeekStart && "rounded-s-lg",
          !isSelectionEnd && isWeekEnd && "rounded-e-lg",
          isSelected && !isSingleDay ? "opacity-100" : "opacity-0",
        )}
      />
      <div
        className={cx(
          "relative flex size-8 items-center justify-center rounded-lg outline-none",
          !isSelected && isHovered && "bg-background-secondary-hover",
          "transition-colors duration-100 ease-out",
          isFocusVisible && "ring-2 ring-inset ring-border-focus-ring",
        )}
      >
        <span
          aria-hidden
          className={cx(
            "absolute inset-0 bg-date-range-edge-background transition-[opacity,border-radius] duration-100 ease-out",
            isSingleDay && "rounded-lg",
            isSelectionStart && !isSingleDay && "rounded-s-lg",
            isSelectionEnd && !isSingleDay && "rounded-e-lg",
            isEdge ? "opacity-100" : "opacity-0",
          )}
        />
        <span
          className={cx(
            "relative text-body-medium text-text-primary",
            (isDisabled || isUnavailable) && "text-text-tertiary",
            // Unavailable days (isDateUnavailable) can be focused but not
            // picked, so they read as struck out rather than just faded.
            isUnavailable && "line-through",
          )}
        >
          {formattedDate}
        </span>
        {/* Opt-in (the standalone Calendar): a dot under today's date. */}
        {showToday && isToday ? (
          <span
            aria-hidden
            className={cx("absolute bottom-1 left-1/2 size-1 -translate-x-1/2 rounded-full", isEdge ? "bg-text-primary" : "bg-accent-500")}
          />
        ) : null}
      </div>
    </div>
  );
}

export function MonthPanel({
  offset,
  showPrev,
  showNext,
  bare = false,
  hideHeader = false,
  showToday = false,
}: {
  offset: number;
  showPrev?: boolean;
  showNext?: boolean;
  /** Skip the panel's own card chrome (width, bg, padding, shadow) so it can
   *  be embedded directly inside a caller-styled container instead — used by
   *  the calendar template's inline month switcher, which supplies its own
   *  card (matching a different surface's border/shadow). */
  bare?: boolean;
  /** Skip the title + prev/next row entirely — used when a caller already
   *  renders its own single month title/nav (the calendar template's month
   *  switcher pill) and only needs the day grid underneath it. */
  hideHeader?: boolean;
  /** Mark today with a dot under its date (the standalone Calendar does). */
  showToday?: boolean;
}) {
  const { locale } = useLocale();
  // Works inside either a RangeCalendar (DateRangePicker) or a plain Calendar
  // (DatePicker) — exactly one of these contexts is non-null depending on
  // which root rendered it, and both expose the same `visibleRange` shape.
  const rangeState = useContext(RangeCalendarStateContext);
  const singleState = useContext(CalendarStateContext);
  const state = rangeState ?? singleState;
  const isRange = rangeState != null;
  const panelDate = state ? state.visibleRange.start.add({ months: offset }) : null;
  const title = panelDate
    ? new Intl.DateTimeFormat(locale, { month: "long", year: "numeric" }).format(panelDate.toDate(getLocalTimeZone()))
    : "";
  // Two-letter weekdays ("Su", "Mo") only work in Latin scripts: cut down,
  // every Arabic name keeps just its article. Other scripts take the
  // locale's narrow names instead.
  const latinWeekdays = /^\p{Script=Latin}/u.test(
    new Intl.DateTimeFormat(locale, { weekday: "short" }).format(new Date(2024, 0, 7)),
  );

  return (
    <div className={bare ? "w-[296px] shrink-0" : "w-[326px] shrink-0 rounded-2xl bg-background-primary-default p-[15px] shadow-xs"}>
      <div className="flex flex-col gap-5">
        {!hideHeader && (
          <div className="flex items-center justify-between">
            {showPrev ? (
              <RACButton
                slot="previous"
                className="flex size-4 cursor-pointer items-center justify-center rounded-[3px] text-text-secondary outline-none transition-colors duration-150 ease hover:bg-background-secondary-hover"
              >
                <ChevronLeft16 />
              </RACButton>
            ) : (
              <span className="size-4" aria-hidden />
            )}
            <span className="flex-1 text-center text-body-medium text-text-primary">{title}</span>
            {showNext ? (
              <RACButton
                slot="next"
                className="flex size-4 cursor-pointer items-center justify-center rounded-[3px] text-text-secondary outline-none transition-colors duration-150 ease hover:bg-background-secondary-hover"
              >
                <ChevronRight16 />
              </RACButton>
            ) : (
              <span className="size-4" aria-hidden />
            )}
          </div>
        )}
        <CalendarGrid
          offset={{ months: offset }}
          weekdayStyle={latinWeekdays ? "short" : "narrow"}
          className="-m-3 self-start border-separate outline-none"
          style={{ borderSpacing: "12px 12px" }}
        >
          <CalendarGridHeader>
            {(day) => (
              <CalendarHeaderCell className="size-6 pb-0 text-center text-body-medium text-text-secondary">
                {latinWeekdays ? day.slice(0, 2) : day}
              </CalendarHeaderCell>
            )}
          </CalendarGridHeader>
          <CalendarGridBody>
            {(date) => (
              <CalendarCell date={date} className="p-0 outline-none">
                {(cellProps) => <DayCell {...cellProps} isRange={isRange} showToday={showToday} />}
              </CalendarCell>
            )}
          </CalendarGridBody>
        </CalendarGrid>
      </div>
    </div>
  );
}

/** One editable "DD/MM/YYYY" chip. Keeps its own draft text while typing so
 *  the field doesn't reformat on every keystroke; commits on blur/Enter,
 *  reverting to the last valid value if the text doesn't parse. */
export function DateChipInput({
  date,
  label,
  onCommit,
}: {
  date: CalendarDate;
  label: string;
  onCommit: (date: CalendarDate) => void;
}) {
  const formatted = formatChipDate(date);
  const [text, setText] = useState(formatted);

  useEffect(() => {
    setText(formatted);
  }, [formatted]);

  const commit = () => {
    const parsed = parseChipDate(text);
    if (parsed) {
      onCommit(parsed);
    } else {
      setText(formatted);
    }
  };

  return (
    <input
      type="text"
      dir="ltr"
      inputMode="numeric"
      value={text}
      onChange={(event) => setText(event.target.value)}
      onBlur={commit}
      onKeyDown={(event) => {
        if (event.key === "Enter") event.currentTarget.blur();
        if (event.key === "Escape") setText(formatted);
      }}
      aria-label={label}
      className="w-[104px] rounded-2lg border border-border-button-default bg-background-primary-default px-2 py-2 text-body-medium text-text-primary shadow-xs outline-none transition-colors duration-100 ease-out focus-visible:border-border-button-active"
    />
  );
}

